import React from 'react';
import styled from 'styled-components';
import katowice from '../../images/katowice.jpg';
import { useSpring, animated, config } from "react-spring";


const Slideshow = () => {
    const slideAnimation = useSpring({
        from: { opacity: 0 },
        to: { opacity: 1 },
        delay: 150,
        config: config.gentle,
    });

    return (
        <SlideContainer style={slideAnimation}>
            <div className="each-slide">
                <div style={{
                    'backgroundImage': `url(${katowice})`,
                    'height': '450px',
                    'width': '1440px',
                    'backgroundPosition': 'center',
                    'backgroundSize': 'cover',
                }}>
                    <TextBox>
                        <TitleSlide>Profesjonalne usługi księgowe</TitleSlide>
                        <SubtitleSlide>Lorem ipsum</SubtitleSlide>
                    </TextBox>

                </div>
            </div>
        </SlideContainer>
    )
}

export default Slideshow

const SlideContainer = styled(animated.div)`
    margin: 8.5rem auto;
    width: 100%;
`;

const TextBox = styled.div`
    position: fixed;
    margin-top: 10rem;
    margin-left: 10rem;
    background-color: blue;
`;

const TitleSlide = styled.h1`
    text-align: center;
    color: white;
`;

const SubtitleSlide = styled.p`
    text-align: center;
    color: white;
`;
